const lines = (value: string) => value.split(/\r?\n/u).map((line) => line.trim()).filter(Boolean);
const words = (value: string) => value.toLocaleLowerCase().match(/[\p{L}\p{N}]+/gu) ?? [];
const escapeHtml = (value: string) => value.replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;").replace(/"/g, "&quot;").replace(/'/g, "&#39;");
const pairs = (value: string) => Object.fromEntries(lines(value).map((line) => { const i = line.indexOf("="); if (i < 1) throw new Error(`Expected key=value: ${line}`); return [line.slice(0, i).trim(), line.slice(i + 1).trim()]; }));
const num = (value: string | undefined, name: string, min = -Infinity) => { const parsed = Number(value); if (!Number.isFinite(parsed) || parsed < min) throw new Error(`${name} must be a number${Number.isFinite(min) ? ` ≥ ${min}` : ""}.`); return parsed; };
const table = (rows: Array<Array<string | number>>) => {
  if (!rows.length) return "";
  const render = (row: Array<string | number>) => `| ${row.map((cell) => String(cell).replace(/\|/g, "\\|")).join(" | ")} |`;
  return [render(rows[0]), render(rows[0].map(() => "---")), ...rows.slice(1).map(render)].join("\n");
};
const format = (value: number, digits = 2) => new Intl.NumberFormat("en-US", { maximumFractionDigits: digits }).format(value);

