function translateGeneratedToken(value: string, locale: Locale) {
  return generatedTerms[value.trim().toLocaleLowerCase("en-US")]?.[locale] ?? value;
}

function splitTableRow(line: string) {
  const value = line.trim().replace(/^\|/, "").replace(/\|$/, "");
  const cells: string[] = [];
  let cell = "";
  for (let index = 0; index < value.length; index += 1) {
    if (value[index] === "\\" && value[index + 1] === "|") { cell += "|"; index += 1; }
    else if (value[index] === "|") { cells.push(cell.trim()); cell = ""; }
    else cell += value[index];
  }
  cells.push(cell.trim());
  return cells;
}

