  tr: { local: "Girdi yalnızca etkin tarayıcı sekmesinde işlenir.", demo: "Örnek veri yükle", clear: "Temizle", input: "İşlenecek veri", second: "Karşılaştırma veya kurallar", mode: "İşlem yönü", run: "Cihazımda çalıştır", running: "İşleniyor…", result: "Sonuç", copy: "Kopyala", download: "İndir", empty: "Aracı çalıştırdığınızda okunabilir sonuç burada görünecek.", done: "Tamamlandı", idle: "Hazır", error: "İşlem tamamlanamadı", expected: "Girdi rehberi", examplePrefix: "Örnek", purpose: "Bu araç ne yapar?", privacy: "Bu işlem tamamen cihazınızda gerçekleşti; girdi ByteQuant sunucusuna gönderilmedi.", jsonGuide: "Geçerli JSON kullanın; çift tırnakları ve kapanan parantezleri koruyun.", pairGuide: "Her ayarı ayrı satırda anahtar=değer biçiminde yazın.", pipeGuide: "Her kayıt ayrı satırda olmalı; alanları | karakteriyle ayırın.", csvGuide: "İlk satır sütun adlarıdır; sonraki satırlar aynı sütun sırasını izler.", lineGuide: "Her kaydı veya öğeyi ayrı bir satıra yazın.", textGuide: "Metni olduğu gibi yazın; araç içeriği cihazınızda inceleyecek." },
  en: { local: "Input is processed only in the active browser tab.", demo: "Load example", clear: "Clear", input: "Data to process", second: "Comparison or rules", mode: "Operation direction", run: "Run on my device", running: "Processing…", result: "Result", copy: "Copy", download: "Download", empty: "Run the tool to see a readable result here.", done: "Completed", idle: "Ready", error: "Could not complete the operation", expected: "Input guide", examplePrefix: "Example", purpose: "What does this tool do?", privacy: "This operation happened entirely on your device; input was not sent to ByteQuant servers.", jsonGuide: "Use valid JSON; keep double quotes and closing brackets balanced.", pairGuide: "Write each setting on a separate key=value line.", pipeGuide: "Put each record on a separate line and separate fields with |.", csvGuide: "The first row contains column names; following rows use the same column order.", lineGuide: "Write each record or item on a separate line.", textGuide: "Write or paste the text as-is; the tool will inspect it on your device." },
  de: { local: "Eingaben werden nur im aktiven Browser-Tab verarbeitet.", demo: "Beispiel laden", clear: "Leeren", input: "Zu verarbeitende Daten", second: "Vergleich oder Regeln", mode: "Vorgangsrichtung", run: "Auf meinem Gerät ausführen", running: "Verarbeitung…", result: "Ergebnis", copy: "Kopieren", download: "Herunterladen", empty: "Nach dem Ausführen erscheint hier ein lesbares Ergebnis.", done: "Abgeschlossen", idle: "Bereit", error: "Vorgang konnte nicht abgeschlossen werden", expected: "Eingabeleitfaden", examplePrefix: "Beispiel", purpose: "Was macht dieses Werkzeug?", privacy: "Der Vorgang fand vollständig auf Ihrem Gerät statt; Eingaben wurden nicht an ByteQuant gesendet.", jsonGuide: "Verwenden Sie gültiges JSON mit passenden Anführungszeichen und Klammern.", pairGuide: "Schreiben Sie jede Einstellung in eine eigene Schlüssel=Wert-Zeile.", pipeGuide: "Jeder Datensatz steht in einer eigenen Zeile; Felder werden mit | getrennt.", csvGuide: "Die erste Zeile enthält Spaltennamen; weitere Zeilen folgen derselben Reihenfolge.", lineGuide: "Schreiben Sie jeden Datensatz oder Eintrag in eine eigene Zeile.", textGuide: "Fügen Sie den Text unverändert ein; das Werkzeug prüft ihn auf Ihrem Gerät." },
