function exampleLine(value: string) {
  const line = value.split(/\r?\n/u).find((item) => item.trim())?.trim() ?? "—";
  return line.length > 120 ? `${line.slice(0, 117)}…` : line;
}

function inputGuide(value: string, t: Record<string, string>) {
  const trimmed = value.trim();
  const first = exampleLine(value);
  let json = false;
  if (/^[\[{]/u.test(trimmed)) try { JSON.parse(trimmed); json = true; } catch { json = false; }
  if (json) return { text: t.jsonGuide, kind: "JSON", example: first };
  const firstLines = lines(value).slice(0, 8);
  if (firstLines.length && firstLines.every((line) => /^[^=\s][^=]*=/.test(line))) {
    const keys = firstLines.map((line) => line.slice(0, line.indexOf("=")).trim()).filter(Boolean);
    return { text: t.pairGuide, kind: "key=value", example: keys.join(" · ") };
  }
  if (first.includes("|")) return { text: t.pipeGuide, kind: `${first.split("|").length} fields`, example: first };
  if (/[,;\t]/u.test(first) && firstLines.length > 1) return { text: t.csvGuide, kind: "CSV", example: first };
  if (firstLines.length > 1) return { text: t.lineGuide, kind: "lines", example: first };
  return { text: t.textGuide, kind: "text", example: first };
}

export function FrontierWorkbench({ slug, locale }: { slug: string; locale: Locale }) {
  const t = ui[locale], demo = frontierDemos[slug] ?? { input: "" }, tool = getTool(slug);
  const options = useMemo(() => modeOptions[slug] ?? [], [slug]);
  const primaryGuide = useMemo(() => inputGuide(demo.input, t), [demo.input, t]);
  const secondaryGuide = useMemo(() => inputGuide(demo.secondary ?? "", t), [demo.secondary, t]);
  const [input, setInput] = useState(""); const [secondary, setSecondary] = useState(""); const [mode, setMode] = useState(options[0]?.[0] ?? "default"); const [output, setOutput] = useState(""); const [metrics, setMetrics] = useState<Array<[string, string | number]>>([]); const [warning, setWarning] = useState(""); const [state, setState] = useState<"idle" | "busy" | "success" | "error">("idle"); const [message, setMessage] = useState("");
  const resetResult = () => { setOutput(""); setMetrics([]); setWarning(""); setState("idle"); setMessage(""); };
  const loadDemo = () => { setInput(demo.input); setSecondary(demo.secondary ?? ""); setMode(demo.mode ?? options[0]?.[0] ?? "default"); resetResult(); };
  async function run() { if (state === "busy") return; setState("busy"); setMessage(t.running); await new Promise<void>((resolve) => requestAnimationFrame(() => resolve())); try { if (!input.trim()) throw new Error(locale === "tr" ? "Önce bir girdi yazın veya örneği yükleyin." : locale === "de" ? "Geben Sie zuerst Daten ein oder laden Sie das Beispiel." : locale === "zh" ? "请先输入数据或加载示例。" : "Enter input or load the example first."); if (dualSlugs.has(slug) && !secondary.trim()) throw new Error(locale === "tr" ? "Bu araç için ikinci alan da gereklidir." : locale === "de" ? "Dieses Werkzeug benötigt auch das zweite Feld." : locale === "zh" ? "此工具还需要填写第二个字段。" : "This tool also requires the second field."); const result = await runFrontierTool(slug, input.slice(0, 200_000), secondary.slice(0, 100_000), mode, locale); setOutput(result.output); setMetrics(result.metrics ?? []); setWarning(result.warning ?? ""); setState("success"); setMessage(t.done); } catch (error) { setOutput(""); setMetrics([]); setWarning(""); setState("error"); setMessage(`${t.error}: ${localizeFrontierError(error, locale)}`); } }
  async function copy() { if (!output) return; try { await navigator.clipboard.writeText(output); setMessage(t.done); } catch { setState("error"); setMessage(t.error); } }
  function download() { if (!output) return; const url = URL.createObjectURL(new Blob([output], { type: "text/plain;charset=utf-8" })); const a = document.createElement("a"); a.href = url; a.download = `bytequant-${slug}.txt`; a.click(); setTimeout(() => URL.revokeObjectURL(url), 0); }
  return <section className="workbench precision-workbench frontier-workbench" aria-busy={state === "busy"} aria-label={tool?.title[locale] ?? t.result}>
    <div className="workbench-bar"><span className="local-status"><i />{t.local}<small>{tool?.title[locale]}</small></span><div className="workbench-bar-actions"><button type="button" className="demo-button" onClick={loadDemo}>{t.demo}</button><button type="button" className="ghost-button" onClick={() => { setInput(""); setSecondary(""); resetResult(); }}>{t.clear}</button></div></div>
    <div className="workbench-grid"><div className="workbench-inputs" data-agent-contract={dualSlugs.has(slug) ? "dual-text-v1" : "single-text-v1"}><div className="frontier-purpose"><strong>{t.purpose}</strong><p>{tool?.short[locale]}</p></div><label className="field-label"><span>{tool?.title[locale]} · {t.input}</span><textarea aria-describedby={`${slug}-input-format`} aria-invalid={state === "error"} aria-errormessage={state === "error" ? `${slug}-error` : undefined} data-agent-input data-agent-key="input" value={input} rows={10} maxLength={200000} onChange={(e) => { setInput(e.target.value); resetResult(); }} spellCheck={false} /><span className="frontier-format" id={`${slug}-input-format`}><span className="frontier-format-head"><b>{t.expected}</b><i>{primaryGuide.kind}</i></span><span>{primaryGuide.text}</span><code>{t.examplePrefix}: {primaryGuide.example}</code></span><small className="field-counter">{input.length.toLocaleString()} / 200,000</small></label>{dualSlugs.has(slug) && <label className="field-label"><span>{t.second}</span><textarea aria-describedby={`${slug}-secondary-format`} aria-invalid={state === "error"} data-agent-input data-agent-key="secondary" value={secondary} rows={6} maxLength={100000} onChange={(e) => { setSecondary(e.target.value); resetResult(); }} spellCheck={false} /><span className="frontier-format" id={`${slug}-secondary-format`}><span className="frontier-format-head"><b>{t.expected}</b><i>{secondaryGuide.kind}</i></span><span>{secondaryGuide.text}</span><code>{t.examplePrefix}: {secondaryGuide.example}</code></span></label>}{options.length > 0 && <label className="field-label compact-field"><span>{t.mode}</span><select data-agent-mode value={mode} onChange={(e) => { setMode(e.target.value); resetResult(); }}>{options.map(([value, label]) => <option key={value} value={value}>{label[locale]}</option>)}</select></label>}<button type="button" className="primary-button run-button" data-agent-run disabled={state === "busy"} onClick={() => void run()}>{state === "busy" ? t.running : t.run}<span aria-hidden="true"> →</span></button></div>
      <div className="result-panel" aria-live="polite" aria-atomic="false"><div className="result-header"><span>{t.result}<small className="frontier-state" data-state={state}>{state === "busy" ? t.running : state === "success" ? t.done : state === "error" ? t.error : t.idle}</small></span><div className="output-actions"><button type="button" disabled={!output} onClick={() => void copy()}>{t.copy}</button><button type="button" disabled={!output} onClick={download}>{t.download}</button></div></div>{metrics.length > 0 && <div className="metric-strip" aria-label={t.result}>{metrics.map(([label, value]) => <div key={label}><strong>{value}</strong><span>{label}</span></div>)}</div>}<StructuredToolOutput output={output} empty={t.empty} />{warning && <ToolNotice locale={locale} notice={{ kind: "warning", text: warning }} />}{state === "error" && <div id={`${slug}-error`}><ToolNotice locale={locale} notice={{ kind: "error", text: message }} /></div>}{state === "success" && <div className="workbench-trust-card"><span aria-hidden="true">✓</span><p>{t.privacy}</p></div>}</div></div>
  </section>;
}
